   381	fn validate_production_plan<'src>(
   382	    ctx: &mut DefinitionContext<'src, '_>,
   383	    kind: DefinitionKind,
   384	    element: ElementId,
   385	    owner: DefinitionOwner,
   386	    transform: Affine,
   387	    bounds: [f64; 4],
   388	    style: &CssPaint<'src>,
   389	    control: &mut dyn WorkControl,
   390	    plan: impl FnOnce(&mut DefinitionContext<'src, '_>, &mut dyn WorkControl) -> Result<ProductionDefinitionPlan<'src>>,
   391	) -> Result<ProductionDefinitionPlan<'src>> {
   392	    owner.validate(ctx)?;
   393	    validate_style(ctx.shared.source(), style, control)?;
   394	    ctx.shared
   395	        .element(element, crate::memory::add(element.0, 1)?, control)?;
   396	    if !vexel_geometry::affine_valid(transform)
   397	        || !bounds.into_iter().all(f64::is_finite)
   398	        || bounds[2] < 0.
   399	        || bounds[3] < 0.
   400	    {
   401	        return Err(invalid(0));
   402	    }
   403	    let plan = plan(ctx, control)?;
   404	    let (definition, mapping) = match &plan {
   405	        ProductionDefinitionPlan::Definition(plan) => (plan, None),
   406	        ProductionDefinitionPlan::Pattern { plan, mapping } => (plan, Some(*mapping)),
   407	    };
   408	    let actual = match &definition.descriptor {
   409	        DefinitionDescriptor::Clip(_) => DefinitionKind::Clip,
   410	        DefinitionDescriptor::Mask(_) => DefinitionKind::Mask,
   411	        DefinitionDescriptor::Pattern(descriptor) => {
   412	            if descriptor.definition != element {
   413	                return Err(invalid(0));
   414	            }
   415	            let map = mapping.ok_or_else(|| invalid(0))?;
   416	            map.pixel_inverse(*descriptor)?;
   417	            let DefinitionTarget::Shape(shape) = owner.target else {
   418	                return Err(invalid(0));
   419	            };
   420	            if ctx
   421	                .builder
   422	                .scene(ctx.scene)?
   423	                .shape(shape)
   424	                .ok_or_else(|| invalid(0))?
   425	                .source
   426	                != map.source_map
   427	                || map.bounds != bounds
   428	            {
   429	                return Err(invalid(0));
   430	            }
   431	            DefinitionKind::Pattern
   432	        }
   433	        DefinitionDescriptor::Marker(_) => DefinitionKind::Marker,
   434	        DefinitionDescriptor::Filter { filter, primitives } => {
   435	            let DefinitionTarget::Group(_) = owner.target else {
   436	                return Err(invalid(0));
   437	            };
   438	            crate::validate::filter(*filter, primitives, control)?;
   439	            for p in primitives {
   440	                control.charge(WorkKind::FilterPixel, 1).map_err(stopped)?;
   441	                if p.source_offset > ctx.shared.source().len() {
   442	                    return Err(invalid(p.source_offset));
   443	                }
   444	            }
   445	            DefinitionKind::Filter
   446	        }
   447	    };
   448	    if actual != kind || (kind != DefinitionKind::Pattern && mapping.is_some()) {
   449	        return Err(invalid(0));
   450	    }
   451	    crate::mask_post::validate_production_post(ctx, kind, None, definition.post, control)?;
   452	    if definition.expansions.len() > 65536 {
   453	        return Err(crate::types::limit(LimitKind::References));
   454	    }
   455	    for expansion in &definition.expansions {
   456	        crate::mask_post::validate_production_post(
   457	            ctx,
   458	            kind,
   459	            Some(expansion.flavor),
   460	            expansion.post,
   461	            control,
   462	        )?;
   463	        control
   464	            .charge(WorkKind::ReferenceProbe, 1)
   465	            .map_err(stopped)?;
   466	        expansion.range.require(ctx.shared.tokens().len(), 0)?;
   467	        validate_style(ctx.shared.source(), &expansion.style, control)?;
   468	        if !vexel_geometry::affine_valid(expansion.transform)
   469	            || !expansion
   470	                .viewport
   471	                .into_iter()
   472	                .all(|v| v.is_finite() && v > 0.)
   473	        {
   474	            return Err(invalid(0));
   475	        }
   476	    }
   477	    control.checkpoint().map_err(stopped)?;
   478	    Ok(plan)
   479	}
